import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, Legend, BarChart, Bar } from 'recharts';
import axios from 'axios';
import Papa from 'papaparse';
import FloatingPandas from './FloatingPandas';
import './App.css';

function App() {
  const [data, setData] = useState([]);
  const [filterHours, setFilterHours] = useState(null);
  const [cumulativeGB, setCumulativeGB] = useState(0);

  // Load historical CSV
  useEffect(() => {
    async function fetchHistory() {
      try {
        const res = await axios.get('http://localhost:5000/stats_history');
        const parsed = Papa.parse(res.data, { header: true, dynamicTyping: true });
        let formatted = parsed.data.map(d => ({
          timestamp: d.timestamp,
          time: new Date(d.timestamp).toLocaleTimeString(),
          downloadSpeed: d.downloadSpeed,
          uploadSpeed: d.uploadSpeed,
          cpuLoad: d.cpuLoad,
          memoryUsed: d.memoryUsed,
          memoryTotal: d.memoryTotal,
        }));

        // Apply filter if any
        if (filterHours) {
          const cutoff = new Date();
          cutoff.setHours(cutoff.getHours() - filterHours);
          formatted = formatted.filter(d => new Date(d.timestamp) >= cutoff);
        }

        setData(formatted);

        // Refined cumulative GB calculation
        let cum = 0;
        formatted.forEach((d, i) => {
          if (i > 0) {
            const prev = formatted[i - 1];
            const avgSpeedMB = (d.downloadSpeed + prev.downloadSpeed) / 2;
            cum += avgSpeedMB / 1024; // MB → GB
          }
        });
        setCumulativeGB(cum.toFixed(2));
      } catch (err) {
        console.error(err);
      }
    }
    fetchHistory();
  }, [filterHours]);

  // Live updates
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const res = await axios.get('http://localhost:5000/stats');
        setData(prev => {
          const newData = [...prev, {
            timestamp: new Date().toISOString(),
            time: new Date().toLocaleTimeString(),
            downloadSpeed: res.data.downloadSpeed,
            uploadSpeed: res.data.uploadSpeed,
            cpuLoad: res.data.cpuLoad,
            memoryUsed: res.data.memoryUsed,
            memoryTotal: res.data.memoryTotal,
          }].slice(-86400); // keep last 24h
          return newData;
        });

        // Update cumulative GB more precisely
        setCumulativeGB(prev => {
          const last = data[data.length - 1];
          const avgSpeedMB = last ? (last.downloadSpeed + res.data.downloadSpeed) / 2 : res.data.downloadSpeed;
          return (parseFloat(prev) + avgSpeedMB / 1024).toFixed(2);
        });
      } catch (err) {
        console.error(err);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [data]);

  return (
    <div style={{ padding: 30 }}>
      <FloatingPandas />

      <h1 style={{ textAlign: 'center', marginBottom: 30 }}>🐼 System & Download Monitor 🐼</h1>

      {/* History Buttons */}
      <div style={{ textAlign: 'center', marginBottom: 30 }}>
        <button onClick={() => setFilterHours(8)}>Last 8 hours</button>
        <button onClick={() => setFilterHours(24)}>Last 24 hours</button>
        <button onClick={() => setFilterHours(null)}>Full history</button>
      </div>

      {/* Network Chart */}
      <div className="chart-container">
        <h2>Network Speed (MB/s) - Cumulative: {cumulativeGB} GB</h2>
        <LineChart width={800} height={200} data={data}>
          <XAxis dataKey="time" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="downloadSpeed" stroke="#8884d8" name="Download" />
          <Line type="monotone" dataKey="uploadSpeed" stroke="#82ca9d" name="Upload" />
        </LineChart>

        <BarChart width={800} height={100} data={data}>
          <XAxis dataKey="time" hide />
          <YAxis hide />
          <Tooltip />
          <Bar dataKey="downloadSpeed" fill="#8884d8" />
          <Bar dataKey="uploadSpeed" fill="#82ca9d" />
        </BarChart>
      </div>

      {/* CPU Chart */}
      <div className="chart-container">
        <h2>CPU Usage (%)</h2>
        <LineChart width={800} height={200} data={data}>
          <XAxis dataKey="time" />
          <YAxis />
          <Tooltip />
          <Line type="monotone" dataKey="cpuLoad" stroke="#ff7300" />
        </LineChart>
      </div>

      {/* Memory Chart */}
      <div className="chart-container">
        <h2>Memory Usage (GB)</h2>
        <LineChart width={800} height={200} data={data}>
          <XAxis dataKey="time" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="memoryUsed" stroke="#82aaff" name="Used" />
          <Line type="monotone" dataKey="memoryTotal" stroke="#ffaa82" name="Total" />
        </LineChart>
      </div>
    </div>
  );
}

export default App;
